// RuleVersionRelations provides type-safe names for Bun eager-loading.
// Use these instead of string literals in .Relation() calls to get compile-time safety.
//
//	q.Relation(RuleVersionRelations.RuleSet)
//	// Bun eager-loads the RuleSet association via a separate query
var RuleVersionRelations = struct {
	RuleSet string
}{
	RuleSet: "RuleSet",
}

// RuleVersionScopeTenant restricts a query to a single tenant by adding:
//
//	WHERE dprv.organization_id = ? AND dprv.business_unit_id = ?
//
// Returns the same *bun.SelectQuery so it can be chained fluently:
//
//	documentparsingrulecol.RuleVersionScopeTenant(sq, ti).
//		Where(documentparsingrulecol.RuleVersionColumns.ID.Eq(), id)
func RuleVersionScopeTenant(q *bun.SelectQuery, ti pagination.TenantInfo) *bun.SelectQuery {
	return buncolgen.ScopeTenant(q, RuleVersionColumns.OrganizationID, RuleVersionColumns.BusinessUnitID, ti)
}

// RuleVersionScopeTenantUpdate restricts an update query to a single tenant.
// Use this inside UpdateQuery.WhereGroup callbacks:
//
//	WhereGroup(" AND ", func(uq *bun.UpdateQuery) *bun.UpdateQuery {
//		return documentparsingrulecol.RuleVersionScopeTenantUpdate(uq, req.TenantInfo).
//			Where(documentparsingrulecol.RuleVersionColumns.ID.In(), bun.List(ids))
//	})
func RuleVersionScopeTenantUpdate(q *bun.UpdateQuery, ti pagination.TenantInfo) *bun.UpdateQuery {
	return buncolgen.ScopeTenantUpdate(q, RuleVersionColumns.OrganizationID, RuleVersionColumns.BusinessUnitID, ti)
}

// RuleVersionScopeTenantDelete restricts a delete query to a single tenant.
// Use this inside DeleteQuery.WhereGroup callbacks:
//
//	WhereGroup(" AND ", func(dq *bun.DeleteQuery) *bun.DeleteQuery {
//		return documentparsingrulecol.RuleVersionScopeTenantDelete(dq, req.TenantInfo).
//			Where(documentparsingrulecol.RuleVersionColumns.ID.Eq(), id)
//	})
func RuleVersionScopeTenantDelete(q *bun.DeleteQuery, ti pagination.TenantInfo) *bun.DeleteQuery {
	return buncolgen.ScopeTenantDelete(q, RuleVersionColumns.OrganizationID, RuleVersionColumns.BusinessUnitID, ti)
}

// RuleVersionApplyTenant returns a closure for SelectQuery.Apply() that scopes to a single tenant.
// Use this instead of wrapping ScopeTenant in an anonymous function:
//
//	q.Apply(documentparsingrulecol.RuleVersionApplyTenant(tenantInfo))
func RuleVersionApplyTenant(ti pagination.TenantInfo) func(*bun.SelectQuery) *bun.SelectQuery {
	return buncolgen.ApplyTenant(RuleVersionColumns.OrganizationID, RuleVersionColumns.BusinessUnitID, ti)
}

